/**
 * Recorded sound effects (Audio 2.0): MP3 variants embedded in the build and decoded once into AudioBuffers.
 *
 * - `assets/sfx/manifest.json` (generated by scripts/audio/build_sfx.py) lists, per SfxId, its variants, the gain
 *   that brings each variant to the id's target loudness, the random pitch/gain spread per play and the level of
 *   the optional synthesized layer.
 * - Decoding starts as soon as the engine exists, on an OfflineAudioContext (no user gesture needed). Until every
 *   variant of an id is decoded the engine keeps playing the synthesized version, which also stays the fallback
 *   for every failure (no OfflineAudioContext, fetch or decode errors, ...). Nothing here throws.
 * - MP3 decoders differ in how much encoder delay / padding they strip, so each decoded buffer is re-aligned:
 *   the near-silent lead-in is cut (the build already trimmed the asset to 0.5 ms before its attack), leaving the
 *   attack <= ~1 ms after the BufferSource start whatever the browser's decoder did; the silent tail is cut too.
 */
import type { SfxId } from './audio';
import manifestJson from './assets/sfx/manifest.json';

interface ManifestId {
  /** asset names, one per variant */
  v: string[];
  /** runtime gain per variant (dB): brings the variant to the id's target loudness */
  g: number[];
  /** random playback-rate spread per play (+-fraction) */
  pv: number;
  /** random gain spread per play (+-fraction) */
  vv: number;
  /** synthesized layer level (dB re its own level) or null for none */
  syn: number | null;
}
interface Manifest {
  version: number;
  sr: number;
  assets: Record<string, { ch: number; dur: number; lk: number }>;
  ids: Record<string, ManifestId>;
}

/** A recorded SfxId ready to play. */
export interface RecSfx {
  /** one aligned buffer per variant */
  bufs: AudioBuffer[];
  /** linear gain per variant */
  gains: number[];
  pitchVar: number;
  volVar: number;
  /** linear gain of the synthesized layer relative to the voice (0 = no synth layer) */
  synth: number;
}

const MANIFEST = manifestJson as unknown as Manifest;
const URLS = import.meta.glob('./assets/sfx/*.mp3', { query: '?url', import: 'default', eager: true }) as Record<string, string>;
/** lead-in below this (re the buffer's peak) is considered silence (decoder delay / priming) */
const LEAD_DB = -50;
/** tail below this (re peak) is cut */
const TAIL_DB = -70;
/** kept before the first sample above LEAD_DB (s) */
const PREROLL = 0.0005;
/** decodes in flight */
const CONCURRENCY = 4;

const dbToGain = (d: number): number => Math.pow(10, d / 20);
type OfflineCtor = new (channels: number, length: number, sampleRate: number) => OfflineAudioContext;

function decode(ac: BaseAudioContext, data: ArrayBuffer): Promise<AudioBuffer> {
  return new Promise<AudioBuffer>((resolve, reject) => {
    try {
      // promise form everywhere modern; callback form for old Safari (both handled, first one wins)
      const p = ac.decodeAudioData(data, resolve, reject) as Promise<AudioBuffer> | undefined;
      if (p && typeof p.then === 'function') p.then(resolve, reject);
    } catch (e) {
      reject(e);
    }
  });
}

/** Trim decoder delay / priming (near-silent lead-in) and the silent tail. Returns null for an all-silent buffer. */
export function alignBuffer(ac: BaseAudioContext, b: AudioBuffer): { buf: AudioBuffer; lead: number } | null {
  const n = b.length;
  const nc = b.numberOfChannels;
  const chans: Float32Array[] = [];
  for (let c = 0; c < nc; c++) chans.push(b.getChannelData(c));
  let pk = 0;
  for (const d of chans) for (let i = 0; i < n; i++) {
    const a = d[i] < 0 ? -d[i] : d[i];
    if (a > pk) pk = a;
  }
  if (!(pk > 1e-6)) return null;
  const lo = pk * dbToGain(LEAD_DB);
  const tl = pk * dbToGain(TAIL_DB);
  let i0 = n;
  let i1 = -1;
  for (const d of chans) {
    for (let i = 0; i < i0; i++) if (d[i] > lo || d[i] < -lo) { i0 = i; break; }
    for (let i = n - 1; i > i1; i--) if (d[i] > tl || d[i] < -tl) { i1 = i; break; }
  }
  const sr = b.sampleRate;
  const start = Math.max(0, i0 - Math.round(PREROLL * sr));
  const end = Math.min(n, i1 + 1 + Math.round(0.002 * sr));
  if (start === 0 && end === n) return { buf: b, lead: 0 };
  const len = Math.max(1, end - start);
  const out = ac.createBuffer(nc, len, sr);
  const fadeN = Math.min(len, Math.round(0.001 * sr));
  for (let c = 0; c < nc; c++) {
    const seg = new Float32Array(len);
    seg.set(chans[c].subarray(start, start + len));
    if (end < n) for (let k = 0; k < fadeN; k++) seg[len - 1 - k] *= k / fadeN; // cut tail: 1 ms fade
    out.copyToChannel(seg, c);
  }
  return { buf: out, lead: start };
}

export class SfxSamples {
  private recs = new Map<SfxId, RecSfx>();
  private started = false;
  /** samples trimmed from each asset's start after decoding (the browser's MP3 decoder delay), for diagnostics */
  readonly lead: Record<string, number> = {};
  /** assets that failed to load */
  readonly failed: string[] = [];
  /** wall-clock ms the whole load took (-1 until finished) */
  loadMs = -1;
  /** resolves when loading has finished (successfully or not) */
  readonly whenDone: Promise<void>;
  private finish!: () => void;

  constructor() {
    this.whenDone = new Promise<void>((r) => (this.finish = r));
  }

  /** The recorded version of an id, or null (not decoded yet / failed: play the synthesized one). */
  get(id: SfxId): RecSfx | null {
    return this.recs.get(id) ?? null;
  }

  /** ids with a recorded version ready */
  get readyIds(): SfxId[] {
    return [...this.recs.keys()];
  }

  /** Start decoding (idempotent). Uses an OfflineAudioContext, or `ctx` where none exists. */
  load(ctx?: BaseAudioContext | null): void {
    if (this.started) return;
    let ac: BaseAudioContext | null = null;
    try {
      const w = (typeof window !== 'undefined' ? window : globalThis) as unknown as { OfflineAudioContext?: OfflineCtor; webkitOfflineAudioContext?: OfflineCtor };
      const Off = w.OfflineAudioContext ?? w.webkitOfflineAudioContext;
      if (Off) ac = new Off(1, 1, MANIFEST.sr || 48000);
    } catch {
      ac = null;
    }
    ac = ac ?? ctx ?? null;
    if (!ac || typeof fetch !== 'function') return; // retried with the real context at unlock
    this.started = true;
    void this.run(ac);
  }

  private async run(ac: BaseAudioContext): Promise<void> {
    const now = () => (typeof performance !== 'undefined' ? performance.now() : Date.now());
    const t0 = now();
    const bufs = new Map<string, AudioBuffer>();
    // asset -> ids using it; an id goes live as soon as all of its variants are decoded
    const users = new Map<string, string[]>();
    for (const [id, m] of Object.entries(MANIFEST.ids)) for (const n of m.v) users.set(n, [...(users.get(n) ?? []), id]);
    const enable = (id: string) => {
      const m = MANIFEST.ids[id];
      const vb = m.v.map((n) => bufs.get(n));
      if (!vb.length || vb.some((b) => !b) || m.g.length !== vb.length) return;
      this.recs.set(id as SfxId, {
        bufs: vb as AudioBuffer[],
        gains: m.g.map(dbToGain),
        pitchVar: m.pv,
        volVar: m.vv,
        synth: m.syn === null || m.syn === undefined ? 0 : dbToGain(m.syn),
      });
    };
    // most frequent sounds first
    const first = ['hit', 'pickup_xp', 'ui_hover', 'ui_click', 'enemy_death', 'pickup_coin', 'player_hurt', 'hit_crit'];
    const rank = (n: string) => {
      const i = first.findIndex((id) => (users.get(n) ?? []).includes(id));
      return i < 0 ? first.length : i;
    };
    const names = Object.keys(MANIFEST.assets).sort((a, b) => rank(a) - rank(b));
    let next = 0;
    const worker = async (): Promise<void> => {
      while (next < names.length) {
        const name = names[next++];
        try {
          const url = URLS['./assets/sfx/' + name + '.mp3'];
          if (!url) throw new Error('missing');
          const res = await fetch(url);
          if (!res.ok) throw new Error('http ' + res.status);
          const decoded = await decode(ac, await res.arrayBuffer());
          const al = alignBuffer(ac, decoded);
          if (!al) throw new Error('silent');
          bufs.set(name, al.buf);
          this.lead[name] = al.lead;
          for (const id of users.get(name) ?? []) enable(id);
        } catch {
          this.failed.push(name);
        }
      }
    };
    try {
      await Promise.all(Array.from({ length: CONCURRENCY }, worker));
    } catch {
      /* keep whatever is ready; everything else stays synthesized */
    }
    this.loadMs = now() - t0;
    this.finish();
  }
}
